import { Group, Mesh, PlaneGeometry, Color } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec2, mix, uniform, float, sin, fract, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.name = 'hub-journal-title';

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'Journal', role: 'headline', typography: { fontSize: 96 } },
    ];
  const headlineItem =
    items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Journal' };

  // ---------------------------------------------------------------------
  // Local engineered-gradient backdrop card (avoids flat void behind title)
  // ---------------------------------------------------------------------
  const rectW = 512;
  const rectH = 320;
  const aspect = rectW / rectH;
  const cardH = 1.15;
  const cardW = cardH * aspect;

  const inkColor = uniform(vec3(new THREE.Color(colors.ink).toArray()));
  const surfaceColor = uniform(vec3(new THREE.Color(colors.surface).toArray()));
  const accentColor = uniform(vec3(new THREE.Color(colors.accent).toArray()));

  const gradientMat = new MeshBasicNodeMaterial();
  const gUv = uv();
  const grainSeed = fract(
    sin(dot(gUv.mul(311.7), vec2(12.9898, 78.233))).mul(43758.5453)
  );
  const grain = grainSeed.sub(0.5).mul(0.03);
  const vertMix = mix(surfaceColor, inkColor, gUv.y);
  const accentEdge = float(1.0).sub(
    gUv.x.sub(0.5).abs().mul(2.0)
  ).mul(0.06);
  const finalColor = vertMix.add(grain).add(accentColor.mul(accentEdge));
  gradientMat.colorNode = finalColor;
  gradientMat.transparent = true;
  gradientMat.opacity = 0.92;
  gradientMat.side = THREE.DoubleSide;

  const backdropGeo = new PlaneGeometry(cardW * 1.12, cardH * 1.3);
  const backdropMesh = new Mesh(backdropGeo, gradientMat);
  backdropMesh.position.set(0, 0, -0.02);
  root.add(backdropMesh);

  // ---------------------------------------------------------------------
  // Accent artwork sprite (billboards toward camera)
  // ---------------------------------------------------------------------
  const accentGeo = new PlaneGeometry(cardW, cardH);
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.transparent = true;
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, 0, 0.01);
  root.add(accentMesh);

  let loadedTexture = null;
  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/floating-accent.png';
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (!tex) return;
      loadedTexture = tex;
      const imgW = tex.image?.width ?? rectW;
      const imgH = tex.image?.height ?? rectH;
      // atlas source rect: 0,0,512,320 -> map against loaded texture's own dims
      const rx = 0 / imgW;
      const ry = 1 - (0 + rectH) / imgH;
      const rw = rectW / imgW;
      const rh = rectH / imgH;
      tex.wrapS = THREE.ClampToEdgeWrapping;
      tex.wrapT = THREE.ClampToEdgeWrapping;
      tex.offset.set(rx, ry);
      tex.repeat.set(rw, rh);
      tex.needsUpdate = true;
      accentMat.map = tex;
      accentMat.needsUpdate = true;
    });
  }

  // Billboard behavior: face camera every frame
  accentMesh.onBeforeRender = (renderer, scene, camera) => {
    root.getWorldQuaternion(accentMesh.quaternion);
    accentMesh.quaternion.copy(camera.quaternion);
  };
  backdropMesh.onBeforeRender = (renderer, scene, camera) => {
    backdropMesh.quaternion.copy(camera.quaternion);
  };

  // ---------------------------------------------------------------------
  // Headline text "Journal"
  // ---------------------------------------------------------------------
  const fontSize = headlineItem.typography?.fontSize ?? 96;
  const textNode = ctx.fontAtlas.createText(String(headlineItem.text ?? 'Journal'), {
    fontSize,
    color: colors.paper,
    align: 'center',
  });
  textNode.position.set(0, 0, 0.03);
  root.add(textNode);

  // Thin accent underline (engineered detail, <=10% of frame, single accent use)
  const underlineGeo = new PlaneGeometry(cardW * 0.42, 0.018);
  const underlineMat = new MeshBasicNodeMaterial();
  underlineMat.colorNode = accentColor;
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.set(0, -cardH * 0.42, 0.03);
  root.add(underline);

  // ---------------------------------------------------------------------
  // Weighted-settle entrance (static composition otherwise; no idle motion
  // beyond the single settle, per "no interactivity" spec)
  // ---------------------------------------------------------------------
  root.scale.setScalar(0.98);
  root.position.y += 0.15;
  const tl = gsap.timeline();
  tl.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }, 0);
  tl.to(root.position, {
    y: root.position.y - 0.15,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  tl.fromTo(
    textNode,
    { position: { z: textNode.position.z } },
    { duration: 0.01 },
    0
  );

  // ---------------------------------------------------------------------
  // Primitives (none specified for this node — ship without primitive)
  // ---------------------------------------------------------------------
  const primitiveHandles = [];
  const primitiveConfigs = config.cinematicPrimitives ?? [];
  for (const prim of primitiveConfigs) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(root, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    for (const h of primitiveHandles) {
      h?.cleanup?.();
    }
    backdropGeo.dispose();
    gradientMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    if (textNode?.userData?.cleanup) {
      textNode.userData.cleanup();
    } else if (textNode?.geometry || textNode?.material) {
      textNode.geometry?.dispose?.();
      textNode.material?.dispose?.();
    }
  };

  return root;
}
